() => {
  const canonical = document.querySelector('link[rel="canonical"]')?.href || 'no canonical';
  const ogUrl = document.querySelector('meta[property="og:url"]')?.content || 'no og:url';
  const currentUrl = window.location.href;
  // Insert URL as visible text on the page for capture
  const div = document.createElement('div');
  div.id = 'dsh-product-url';
  div.textContent = 'PRODUCT_URL: https://www.amazon.com/dp/B01N6T5QNO';
  document.body.appendChild(div);
  return { canonical, ogUrl, currentUrl };
}

